@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--ink:#eef0e9;--muted:#9ba3a5;--gold:#e5c785;--teal:#78d8c0;--panel:rgba(13,19,29,.92)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#080d15;color:var(--ink);font-family:Manrope,system-ui,sans-serif;touch-action:none}#game-shell{position:relative;width:min(100vw,177.7778vh);height:min(100vh,56.25vw);max-width:1280px;max-height:720px;margin:auto;top:50%;transform:translateY(-50%);overflow:hidden;background:#101a25;box-shadow:0 20px 90px #000b}canvas{width:100%;height:100%;display:block;image-rendering:pixelated}.screen{position:absolute;inset:0;display:flex;align-items:center;padding:8% 9%;background:linear-gradient(90deg,rgba(6,11,19,.9),rgba(7,12,20,.61) 49%,rgba(7,12,20,.05));z-index:3}.hidden{display:none!important}.title-copy{max-width:490px}.eyebrow{font:500 10px 'DM Mono',monospace;letter-spacing:.24em;color:#d4be89}.eyebrow i{display:inline-block;width:17px;height:1px;background:#d4be89;vertical-align:middle;margin:0 9px}.title-copy h1{font-size:clamp(72px,12vw,138px);line-height:.83;letter-spacing:.13em;margin:28px 0 11px;font-weight:800;text-shadow:0 0 32px #9dc0ca44}.subtitle{font:500 15px 'DM Mono',monospace;letter-spacing:.44em;color:var(--gold);margin-left:7px}.title-copy p{font-size:14px;line-height:1.9;color:#c5ccca;margin:30px 0 29px}.title-actions{display:flex;gap:12px;align-items:center}button{font:600 10px 'DM Mono',monospace;letter-spacing:.11em;color:var(--ink);cursor:pointer}button:focus-visible{outline:2px solid var(--teal);outline-offset:3px}.primary,.secondary{height:44px;padding:0 19px;border:1px solid #e5c785;background:#dbc18b;color:#171c20;transition:.18s}.primary:hover{background:#f0d9a7;transform:translateY(-2px)}.primary span{font-size:17px;margin-left:12px}.secondary{border-color:#ffffff36;background:#18222caa;color:#e5e9e5}.secondary:hover{border-color:var(--teal);color:var(--teal)}.title-foot{font:9px 'DM Mono',monospace;letter-spacing:.08em;color:#a6b0ae;margin-top:55px}.title-mark{position:absolute;right:9%;bottom:9%;font-size:41px;color:#dfc58b77;text-align:center}.title-mark small{display:block;font:9px 'DM Mono',monospace;letter-spacing:.18em;color:#c7c9c4;margin-top:12px}.scanlines{position:absolute;inset:0;pointer-events:none;z-index:5;opacity:.11;background:repeating-linear-gradient(0deg,transparent 0 3px,#000 4px 5px);mix-blend-mode:multiply}
#hud{position:absolute;inset:0;z-index:2;pointer-events:none}.hud-left,.hud-right,.region-tag{position:absolute;top:22px}.hud-left{left:24px;display:flex;gap:11px;align-items:center}.portrait{width:43px;height:43px;border:1px solid #d6bd83;background:#152733;color:#e3c682;display:grid;place-items:center;font-size:23px;box-shadow:0 0 18px #5fe0c433}.bars{width:176px}.bar{height:7px;background:#080e17cc;border:1px solid #ffffff24;overflow:hidden}.bar span{display:block;height:100%;transition:width .22s}.hp span{background:linear-gradient(90deg,#d65d65,#f39d78)}.mp span{background:linear-gradient(90deg,#4c9fbc,#80d9ce)}.level-line{display:flex;justify-content:space-between;font:9px 'DM Mono',monospace;color:#e5e5dd;margin-top:6px}.level-line span{color:#c4c6be}.mp{margin-top:5px;height:5px}.region-tag{left:50%;transform:translateX(-50%);text-align:center;top:25px;font:10px 'DM Mono',monospace;letter-spacing:.16em;color:#ede5cf}.region-tag .tiny-diamond{color:var(--gold);font-size:8px;margin-right:8px}.region-tag small{display:block;color:#a8b7b2;font-size:8px;letter-spacing:.2em;margin-top:6px}.hud-right{right:23px;display:flex;align-items:center;gap:10px}.relic-count{font:16px 'DM Mono',monospace;color:var(--gold);text-align:right;margin-right:7px}.relic-count small{font-size:8px;color:#b8c0bd;display:block;letter-spacing:.13em}.icon-btn{pointer-events:auto;border:1px solid #ffffff45;background:#0d1822c9;width:36px;height:36px;font-size:15px}.icon-btn:hover{color:var(--gold);border-color:var(--gold)}.bossbar{position:absolute;top:76px;left:50%;transform:translateX(-50%);width:min(360px,70vw);font:10px 'DM Mono',monospace;letter-spacing:.13em;text-align:center;color:#e7d9c2}.bossbar>div:first-child{margin-bottom:7px}.bossbar>div span{color:#9ba5a5;font-size:8px;margin-left:8px}.bossbar .bar{height:8px;border-color:#a7615d;background:#231415}.bossbar .bar span{background:linear-gradient(90deg,#963b4e,#ef8a72)}.hint{position:absolute;bottom:80px;left:50%;transform:translateX(-50%);background:#09131bd9;border:1px solid #ffffff35;padding:9px 14px;font:10px 'DM Mono',monospace;letter-spacing:.1em;color:#e9dfc8;white-space:nowrap}.toast{position:absolute;left:50%;top:24%;transform:translate(-50%,-8px);padding:10px 18px;background:#101a22e8;border:1px solid #d6bd8366;color:#ead8ae;font:10px 'DM Mono',monospace;letter-spacing:.1em;opacity:0;transition:.25s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}
.panel-screen{justify-content:center;text-align:center;background:radial-gradient(ellipse at 50% 50%,#0b1118bb,#070b12e8)}.panel{position:relative;width:min(440px,90%);padding:34px 42px;border:1px solid #d4bd8255;background:var(--panel);box-shadow:0 20px 80px #0009}.panel h2{font-size:33px;letter-spacing:.16em;margin:13px 0 25px}.panel>button{display:block;width:100%;margin:10px 0}.panel .primary{margin-top:22px}.text-btn{background:none;border:0;color:#a9b0ad;padding:11px}.text-btn:hover{color:var(--gold)}.key-note{font:8px 'DM Mono',monospace;letter-spacing:.13em;color:#8f9a99;margin-top:24px}.inventory-panel{width:min(570px,92%);text-align:left}.inventory-panel h2{margin-bottom:23px}.close-btn{position:absolute;right:15px;top:13px;background:none;border:0;font:25px sans-serif;color:#c1c6c1}.inventory-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.item-card{border:1px solid #ffffff22;background:#ffffff06;padding:13px 8px;text-align:center}.item-card b{display:block;color:var(--gold);font-size:21px;margin-bottom:8px}.item-card strong{display:block;font:15px 'DM Mono',monospace}.item-card span{display:block;font:7px 'DM Mono',monospace;color:#a8b2ae;letter-spacing:.08em;margin-top:7px}.lore-card{margin-top:20px;padding:13px 15px;border-left:2px solid var(--gold);background:#ffffff08}.lore-card span{font:8px 'DM Mono',monospace;letter-spacing:.18em;color:var(--gold)}.lore-card p{font-size:12px;line-height:1.7;color:#d1d6d1;margin:7px 0 0}.dialog{position:absolute;inset:0;z-index:4;display:flex;align-items:flex-end;justify-content:center;padding:24px 8% 34px;background:linear-gradient(transparent 45%,#050a11cc)}.dialog-box{width:min(760px,100%);padding:19px 24px;background:#0c141eeF;border:1px solid #dbc38c99;box-shadow:0 10px 30px #0009}.dialog-box div{font:9px 'DM Mono',monospace;letter-spacing:.2em;color:var(--gold)}.dialog-box p{font-size:13px;line-height:1.8;min-height:44px;color:#e4e6df}.dialog-box button{float:right;background:none;border:0;color:#e2c888;padding:5px 0}.touch-controls{display:none;pointer-events:none}.touch-controls button{pointer-events:auto;user-select:none;-webkit-user-select:none;touch-action:none;background:#101b25aa;border:1px solid #ffffff44;border-radius:50%;width:48px;height:48px;color:#eef1e8;font-size:13px}.move-pad,.action-pad{position:absolute;bottom:16px;display:flex;gap:8px}.move-pad{left:15px}.action-pad{right:13px;display:grid;grid-template-columns:repeat(3,44px);gap:5px}.action-pad button{width:42px;height:42px;font-size:9px}.action-pad .jump{background:#426956ba}.action-pad .attack{background:#774c50ca}.action-pad .special{background:#565083c9}.action-pad .interact{font-size:12px}.end-placeholder{color:#bac2bf;line-height:1.8}
@media(max-width:700px){#game-shell{width:100vw;height:100dvh;max-height:none;top:0;transform:none}.screen{padding:10% 8%;align-items:center}.title-copy{max-width:78%}.title-copy h1{font-size:clamp(65px,18vw,112px)}.title-copy p{font-size:12px;margin:20px 0}.title-foot{font-size:7px;margin-top:30px}.title-mark{right:7%;bottom:7%;font-size:28px}.eyebrow{font-size:8px}.hud-left{top:12px;left:11px;gap:7px}.portrait{width:34px;height:34px;font-size:18px}.bars{width:min(35vw,145px)}.hud-right{top:12px;right:10px;gap:5px}.icon-btn{width:31px;height:31px}.relic-count{font-size:13px;margin-right:2px}.region-tag{top:59px;font-size:8px}.region-tag small{font-size:7px;margin-top:3px}.bossbar{top:90px}.hint{bottom:112px;font-size:8px}.touch-controls{display:block}.scanlines{opacity:.07}.panel{padding:28px 22px}.panel h2{font-size:27px}.inventory-grid{gap:5px}.item-card{padding:10px 4px}.item-card span{font-size:6px}.dialog{padding:15px 5% 90px}.dialog-box{padding:14px 16px}.dialog-box p{font-size:11px}.title-mark small{font-size:7px}}
@media(max-height:460px) and (min-width:701px){.title-copy h1{font-size:75px;margin:15px 0 8px}.title-copy p{margin:14px 0}.title-foot{margin-top:18px}.title-mark{bottom:5%}}

(()=>{'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
let W=960,H=540,scale=1,gameState='title',last=0,now=0,cam=0,toastTimer=0,dialogLines=[],dialogIndex=0,dialogAction=null,inventoryOpen=false;
const $=s=>document.querySelector(s),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a);
const held=new Set(),pressed=new Set();let touch={left:false,right:false,jump:false,attack:false,dash:false,special:false,interact:false};
function resize(){const r=document.querySelector('#game-shell').getBoundingClientRect();const ratio=r.width/r.height;H=540;W=Math.max(360,Math.round(H*ratio));canvas.width=W;canvas.height=H;}
window.addEventListener('resize',resize);resize();
const worldEnd=4300,groundY=456;
const player={x:100,y:groundY-42,vx:0,vy:0,w:25,h:40,face:1,hp:100,maxHp:100,mp:70,maxMp:70,xp:0,level:1,echoes:0,potions:2,seals:0,kills:0,ground:true,jumps:0,attackCd:0,skillCd:0,dashCd:0,dashTime:0,invuln:0,anim:0,attackTime:0,dead:false};
let enemies=[],projectiles=[],particles=[],pickups=[],boss=null,checkpoint=0,dialogued=new Set(),worldTime=0,saveClock=0;
const platforms=[{x:210,y:370,w:100},{x:430,y:325,w:115},{x:710,y:375,w:105},{x:960,y:340,w:120},{x:1220,y:370,w:105},{x:1480,y:330,w:120},{x:1740,y:375,w:105},{x:1990,y:330,w:115},{x:2240,y:370,w:110},{x:2500,y:330,w:125},{x:2780,y:365,w:100},{x:3040,y:325,w:120},{x:3300,y:370,w:110},{x:3570,y:330,w:120},{x:3840,y:365,w:110}];
const regions=[{x:0,name:'FLORESTA DO VÉU',sky:['#172c39','#315248'],ground:'#273b32',accent:'#8ac4a4'},{x:900,name:'GRUTAS DE MURMÚRIO',sky:['#1b2234','#3e3548'],ground:'#343342',accent:'#b59bd0'},{x:1800,name:'VILA SEM NOME',sky:['#2b2935','#63504a'],ground:'#4a3c39',accent:'#d7aa83'},{x:2700,name:'RUÍNAS DE ASTRÁRIA',sky:['#172d3a','#35605d'],ground:'#314649',accent:'#9dd9cd'},{x:3600,name:'CASTELO DO VÉU',sky:['#181b30','#44304b'],ground:'#302b3e',accent:'#d8a6bb'}];
const lore=['“A floresta não esquece aqueles que caminham em silêncio.”','“Sob a pedra, os sinos ainda contam os nomes perdidos.”','“A vila partiu numa noite. As portas ficaram abertas.”','“Três selos. Uma memória. E uma coroa feita de vazio.”','“Você já esteve aqui, pequena chama. Antes de haver sombras.”'];
function save(){try{localStorage.setItem('umbra-save',JSON.stringify({x:player.x,hp:player.hp,mp:player.mp,xp:player.xp,level:player.level,echoes:player.echoes,potions:player.potions,seals:player.seals,kills:player.kills,checkpoint,dialogued:[...dialogued]}));}catch(e){}}
function load(){try{const s=JSON.parse(localStorage.getItem('umbra-save'));if(!s)return false;Object.assign(player,{x:s.x||100,hp:s.hp||100,mp:s.mp||70,xp:s.xp||0,level:s.level||1,echoes:s.echoes||0,potions:s.potions||2,seals:s.seals||0,kills:s.kills||0});checkpoint=s.checkpoint||0;dialogued=new Set(s.dialogued||[]);player.y=groundY-player.h;return true;}catch(e){return false;}}
function updateContinue(){const ok=!!localStorage.getItem('umbra-save');$('#continue-game').classList.toggle('hidden',!ok);}
const worldObjects=[{x:520,type:'shrine',id:'shrine1'},{x:1370,type:'relic',id:'relic1'},{x:1870,type:'villager',id:'village'},{x:2350,type:'relic',id:'relic2'},{x:3190,type:'shrine',id:'shrine2'},{x:3450,type:'relic',id:'relic3'},{x:3930,type:'altar',id:'altar'}];
function resetGame(){Object.assign(player,{x:100,y:groundY-40,vx:0,vy:0,hp:100,maxHp:100,mp:70,maxMp:70,xp:0,level:1,echoes:0,potions:2,seals:0,kills:0,ground:true,jumps:0,dead:false});checkpoint=0;dialogued.clear();enemies=[];projectiles=[];particles=[];pickups=[];boss=null;spawnWorld();save();startPlay();}
function startPlay(){gameState='play';$('#title-screen').classList.add('hidden');$('#pause-screen').classList.add('hidden');$('#end-screen').classList.add('hidden');$('#hud').classList.remove('hidden');$('#dialog-screen').classList.add('hidden');updateHUD();}
function spawnWorld(){enemies=[];for(let i=0;i<20;i++){const x=310+i*198+rand(-35,35);if(x>worldEnd-400)continue;enemies.push({x,y:groundY-29,w:25,h:29,hp:i%6===5?52:30,maxHp:i%6===5?52:30,type:i%6===5?'wraith':'shade',speed:i%6===5?38:29,dir:i%2?1:-1,hit:0,attack:0,awake:true,dead:false,phase:rand(0,6)});}}
function beginLoaded(){if(!load())return;spawnWorld();startPlay();}
function showToast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');toastTimer=2.2;}
function updateHUD(){const pct=100*player.hp/player.maxHp;$('#hp-fill').style.width=pct+'%';$('#mp-fill').style.width=100*player.mp/player.maxMp+'%';$('#level').textContent='NÍVEL '+player.level;$('#xp-label').textContent=`${player.xp} / ${player.level*40} XP`;
$('#relics').textContent=player.echoes;$('#inv-echoes').textContent=player.echoes;$('#inv-potions').textContent=player.potions;$('#inv-seals').textContent=`${player.seals} / 3` ;$('#inv-kills').textContent=player.kills;
const reg=[...regions].reverse().find(r=>player.x>=r.x)||regions[0];$('#region-name').textContent=reg.name;$('#objective').textContent=player.seals>=3?'ENCONTRE O GUARDIÃO':'ENCONTRE OS ECOS';$('#bossbar').classList.toggle('hidden',!boss||boss.dead);if(boss)$('#boss-fill').style.width=100*boss.hp/boss.maxHp+'%';}
function levelUp(){while(player.xp>=player.level*40){player.xp-=player.level*40;player.level++;player.maxHp+=15;player.hp=player.maxHp;player.maxMp+=8;player.mp=player.maxMp;showToast(`NÍVEL ${player.level} — SUA CHAMA SE FORTALECE`);burst(player.x+12,player.y+20,'#e7d095',24);}}
function gainXP(n){player.xp+=n;levelUp();updateHUD();save();}
function startBoss(){if(boss)return;boss={x:4070,y:groundY-78,w:68,h:78,hp:360,maxHp:360,phase:0,timer:1.2,hit:0,dead:false};showToast('O DEVORADOR DESPERTOU');}
function openDialog(id,lines,action){if(dialogued.has(id)&&id!=='altar')return;dialogLines=lines;dialogIndex=0;dialogAction=action||null;$('#dialog-speaker').textContent=id==='village'?'MAEIRA, A ÚLTIMA MORADORA':'VOZ DO VÉU';$('#dialog-text').textContent=dialogLines[0];$('#dialog-screen').classList.remove('hidden');gameState='dialog';}
function nextDialog(){dialogIndex++;if(dialogIndex>=dialogLines.length){$('#dialog-screen').classList.add('hidden');gameState='play';if(dialogAction)dialogAction();dialogAction=null;return;}$('#dialog-text').textContent=dialogLines[dialogIndex];}
function interact(){const obj=worldObjects.find(o=>Math.abs(o.x-player.x)<64);if(!obj){showToast('NÃO HÁ NADA POR PERTO');return;}if(obj.type==='relic'){if(dialogued.has(obj.id)){showToast('O ECO JÁ FOI RECOLHIDO');return;}dialogued.add(obj.id);player.echoes+=1;player.seals++;player.mp=player.maxMp;gainXP(25);burst(obj.x,groundY-35,'#f1d88e',30);showToast('SELO DO VÉU RECUPERADO  ✧');save();return;}
if(obj.type==='shrine'){openDialog(obj.id,['A pedra pulsa sob seus dedos. Uma lembrança que não é sua atravessa a névoa.','“Quando três sinos soarem, a porta se abrirá. Mas não deixe que ele escute seu nome.”'],()=>{dialogued.add(obj.id);player.hp=player.maxHp;player.mp=player.maxMp;checkpoint=obj.x;showToast('SANTUÁRIO ATIVADO — VIDA RESTAURADA');save();});return;}
if(obj.type==='villager'){openDialog(obj.id,['Você chegou tarde demais… ou talvez cedo demais. Já não sei distinguir.','Os três selos mantêm o Devorador adormecido. Leve-os ao castelo. E, se ele chamar você pelo nome… não responda.'],()=>{dialogued.add(obj.id);player.potions++;save();showToast('MAEIRA ENTREGOU UMA ERVA DE CURA');});return;}
if(obj.type==='altar'){if(player.seals<3){showToast(`O ALTAR EXIGE 3 SELOS (${player.seals}/3)`);return;}openDialog(obj.id,['Os três selos se acendem. A coroa de pedra se parte ao meio.','A sombra se ergue — e reconhece o rosto que vê refletido em você.'],()=>{startBoss();dialogued.add(obj.id);});}}

input.newString:
if(obj.type==='altar'){if(player.seals<3){showToast(`O ALTAR EXIGE 3 SELOS (${player.seals}/3)`);return;}openDialog(obj.id,['Os três selos se acendem. A coroa de pedra se parte ao meio.','A sombra se ergue — e reconhece o rosto que vê refletido em você.'],()=>{startBoss();dialogued.add(obj.id);});}}
function setPaused(){if(gameState==='play'){gameState='pause';$('#pause-screen').classList.remove('hidden');}else if(gameState==='pause'){gameState='play';$('#pause-screen').classList.add('hidden');}}
function toggleInventory(){if(gameState==='play'){gameState='inventory';$('#inventory-screen').classList.remove('hidden');}else if(gameState==='inventory'){gameState='play';$('#inventory-screen').classList.add('hidden');}}
function doAttack(){if(player.attackCd>0)return;player.attackCd=.38;player.attackTime=.22;const reach=58,px=player.x+player.w/2+player.face*reach*.55;burst(px,player.y+20,'#f1cb83',7);let hit=false;for(const e of enemies){if(!e.dead&&Math.abs((e.x+e.w/2)-px)<reach*.75&&Math.abs(e.y-player.y)<53){damageEnemy(e,24+player.level*3);hit=true;}}
if(boss&&!boss.dead&&Math.abs((boss.x+boss.w/2)-px)<68&&Math.abs(boss.y-player.y)<90){boss.hp-=30+player.level*3;boss.hit=.2;hit=true;if(boss.hp<=0)winGame();}if(hit){player.mp=Math.min(player.maxMp,player.mp+4);updateHUD();}}
function castSpell(){if(player.skillCd>0||player.mp<22){showToast(player.mp<22?'ENERGIA INSUFICIENTE':'HABILIDADE RECARGANDO');return;}player.mp-=22;player.skillCd=.72;projectiles.push({x:player.x+player.w/2+player.face*19,y:player.y+16,vx:player.face*390,life:1.6,damage:42+player.level*4,color:'#a6e6dc'});burst(player.x+player.w/2,player.y+18,'#8fe5da',12);updateHUD();}
function dodge(){if(player.dashCd>0)return;player.dashCd=.85;player.dashTime=.22;player.vx=player.face*420;player.invuln=.34;burst(player.x+12,player.y+25,'#91d8d0',8);}
function usePotion(){if(player.potions<=0){showToast('SEM ERVAS DE CURA');return;}if(player.hp>=player.maxHp){showToast('SUA VIDA JÁ ESTÁ COMPLETA');return;}player.potions--;player.hp=Math.min(player.maxHp,player.hp+45);burst(player.x+12,player.y+10,'#8bd29b',16);updateHUD();save();showToast('ERVA DE CURA USADA  +45 VIDA');}
function damageEnemy(e,n){if(e.hit>0)return;e.hp-=n;e.hit=.22;burst(e.x+e.w/2,e.y+12,'#dc9b88',8);if(e.hp<=0){e.dead=true;player.kills++;player.echoes++;pickups.push({x:e.x+10,y:e.y-5,type:'echo',life:14});gainXP(18);}}
function hurt(n,sourceX){if(player.invuln>0)return;player.hp-=n;player.invuln=.75;player.vy=-190;player.vx=(player.x<sourceX?-1:1)*180;burst(player.x+12,player.y+20,'#e56f72',11);updateHUD();if(player.hp<=0)loseGame();}
function burst(x,y,color,n){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-120,120),vy:rand(-160,50),life:rand(.25,.65),max:.65,color,size:rand(2,5)});}
function loseGame(){gameState='end';player.dead=true;$('#hud').classList.add('hidden');$('#end-screen').classList.remove('hidden');$('#end-eyebrow').textContent='A CHAMA SE APAGA';$('#end-title').textContent='VOCÊ CAIU';$('#end-copy').textContent='As sombras ainda guardam sua lembrança. O santuário mais próximo aguarda.';$('#restart').textContent='TENTAR NOVAMENTE →';}
function winGame(){boss.dead=true;burst(boss.x+34,boss.y+30,'#f0d48f',60);gameState='end';$('#hud').classList.add('hidden');$('#end-screen').classList.remove('hidden');$('#end-eyebrow').textContent='O VÉU SE FECHA';$('#end-title').textContent='A MEMÓRIA RETORNA';$('#end-copy').textContent='Você se lembra: a última guardiã não salvou o mundo. Ela o selou. E o Devorador era a parte de você que ficou para trás.';$('#restart').textContent='JOGAR NOVAMENTE →';localStorage.removeItem('umbra-save');}
