function bind(){
$('#new-game').addEventListener('click',resetGame);$('#continue-game').addEventListener('click',beginLoaded);$('#pause-btn').addEventListener('click',setPaused);$('#resume').addEventListener('click',setPaused);$('#inventory-btn').addEventListener('click',toggleInventory);$('#open-inventory').addEventListener('click',()=>{gameState='inventory';$('#pause-screen').classList.add('hidden');$('#inventory-screen').classList.remove('hidden');});$('#close-inventory').addEventListener('click',toggleInventory);$('#settings-btn').addEventListener('click',()=>showToast('ÁUDIO AMBIENTE ATIVO  ·  CONTROLES: TECLADO / TOQUE'));$('#to-title').addEventListener('click',()=>{save();gameState='title';$('#pause-screen').classList.add('hidden');$('#hud').classList.add('hidden');$('#title-screen').classList.remove('hidden');updateContinue();});$('#dialog-next').addEventListener('click',nextDialog);$('#restart').addEventListener('click',()=>{if(player.dead){player.dead=false;player.hp=Math.max(50,Math.round(player.maxHp*.55));player.mp=player.maxMp;player.x=checkpoint||100;player.y=groundY-player.h;player.vx=player.vy=0;player.invuln=1.5;if(boss)boss=null;spawnWorld();save();startPlay();}else resetGame();});$('#end-menu').addEventListener('click',()=>{gameState='title';$('#end-screen').classList.add('hidden');$('#title-screen').classList.remove('hidden');$('#hud').classList.add('hidden');updateContinue();});
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','Space','Tab'].includes(e.code))e.preventDefault();if(!held.has(e.code))pressed.add(e.code);held.add(e.code);if(e.repeat)return;if(e.code==='Escape'||e.code==='KeyP'){if(gameState==='play'||gameState==='pause')setPaused();else if(gameState==='inventory')toggleInventory();}if((e.code==='KeyI'||e.code==='Tab')&&gameState==='play'||(e.code==='KeyI'||e.code==='Tab')&&gameState==='inventory')toggleInventory();if(e.code==='Enter'&&gameState==='dialog')nextDialog();});window.addEventListener('keyup',e=>held.delete(e.code));
document.querySelectorAll('[data-action]').forEach(btn=>{const action=btn.dataset.action;btn.addEventListener('pointerdown',e=>{e.preventDefault();btn.setPointerCapture(e.pointerId);if(action==='left'||action==='right')touch[action]=true;else if(action==='attack')touch.attack=true;else pressed.add(({jump:'touchJump',dash:'touchDash',special:'touchSpecial',interact:'touchInteract'})[action]);});const release=e=>{if(action==='left'||action==='right')touch[action]=false;if(action==='attack')touch.attack=false;};btn.addEventListener('pointerup',release);btn.addEventListener('pointercancel',release);btn.addEventListener('lostpointercapture',release);});
$('#game').addEventListener('contextmenu',e=>e.preventDefault());
}
spawnWorld();bind();updateContinue();requestAnimationFrame(frame);
})();

